      volume: 0.08,
      loop: -1,
      duration: -2,
      'fade-out': 2
    }
  ],

  scenes: $('Merge Hybrid Scenes').all()
    .sort((a, b) => {
      const aNum = (a.json && a.json.sceneNumber !== undefined) ? a.json.sceneNumber : 0;
