const staticData = $getWorkflowStaticData('global');
const sceneNum = 1;
const keys = $('Config: Primary Video Master1').first().json.keys;

// ALWAYS read from static filter nodes as the absolute source of truth!
const vidFilter = $('Filter Video Scene1').first().json;

if (staticData['videoKeyIndex_1'] === undefined) {
