if (!topicBrief.genre) topicBrief.genre = 'Entertainment';
if (!topicBrief.visualStyle) topicBrief.visualStyle = 'Cinematic Realistic';
if (!topicBrief.language) topicBrief.language = 'Hinglish';
if (!topicBrief.storyBrief) topicBrief.storyBrief = rawInput;
if (!topicBrief.specificTopic) topicBrief.specificTopic = rawInput;
if (!topicBrief.targetAudience) topicBrief.targetAudience = 'Youth 15-35';
if (!topicBrief.toneStyle) topicBrief.toneStyle = 'Engaging and Cinematic';

let staticData = $getWorkflowStaticData('global');
