return [{ json: topicBrief }];

// Parse Duplicate Check - Fuzzy match against existing topics
const allRows = $input.all().map(r => r.json);
const topicBrief = $('Parse Topic Analyzer Output').first().json || {};
const newTopic = (topicBrief.specificTopic || '').toLowerCase().trim();
const newInput = (topicBrief.rawUserInput || '').toLowerCase().trim();

function normalizeStr(s) {
  return s.toLowerCase().trim().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ');
}

function wordsOverlap(a, b) {
  const wordsA = new Set(normalizeStr(a).split(' ').filter(w => w.length > 3));
  const wordsB = normalizeStr(b).split(' ').filter(w => w.length > 3);
  if (wordsA.size === 0) return false;
  const matches = wordsB.filter(w => wordsA.has(w)).length;
  return matches / Math.max(wordsA.size, 1) > 0.6;
}

let isDuplicate = false;
let matchedTitle = '';

for (const row of allRows) {
  const existingTopic = (row['Detected Topic'] || row['C'] || '').toLowerCase();
  const existingTitle = (row['Story Title'] || row['F'] || '').toLowerCase();

  if (existingTopic && (wordsOverlap(newTopic, existingTopic) || wordsOverlap(newInput, existingTopic))) {
    isDuplicate = true;
    matchedTitle = row['Story Title'] || existingTopic;
    break;
  }
  if (existingTitle && wordsOverlap(newInput, existingTitle)) {
    isDuplicate = true;
    matchedTitle = existingTitle;
    break;
  }
}

return [{ json: { isDuplicate, matchedTitle, newTopic, topicBrief } }];

